(* [comment removed for export] *)
Lemma parser_at_x : forall segs (M M' : word -> option byte) (Sg : Z -> Prop) P ps st' (w' : option (Z * Z)),
  (forall a, Sg a -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
  PTA.out Sg P 160 -> PTA.out Sg (P + 184) 16 -> PTA.out Sg (P + 209) 63 -> PTA.out Sg (PML.ps_bptr ps) (PML.ps_bcap ps) -> PTA.out Sg (PML.ps_sb ps) (Z.of_nat (length (PML.ps_stack ps))) ->
  PMLA.parser_at segs IC M P ps ->
  match w' with
  | None => PML.ps_win ps = None /\ L5.u64_at segs M' (P + 200) 0
  | Some (p', e) => (exists p0, PML.ps_win ps = Some (p0, e)) /\ p' <= e /\ L5.u64_at segs M' (P + 200) p'
  end ->
  L5.u8_at segs M' (P + 208) st' ->
  (forall i, 0 <= i < 272 -> M' (Z_to_bv 64 (P + i)) <> None) ->
